import csv

# Verify all stop_name, stop_lat, stop_lon match the input
stops = {}
with open('outputs/t05_clean_stops.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stops[row['stop_id']] = {
            'stop_name': row['stop_name'],
            'stop_lat': row['stop_lat'],
            'stop_lon': row['stop_lon']
        }

with open('outputs/t06_stop_service_intensity.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stop_id = row['stop_id']
        if stop_id not in stops:
            print(f'Missing stop: {stop_id}')
        else:
            s = stops[stop_id]
            if row['stop_name'] != s['stop_name']:
                print(f'Mismatch stop_name for {stop_id}: {row[\"stop_name\"]} != {s[\"stop_name\"]}')
            if row['stop_lat'] != s['stop_lat']:
                print(f'Mismatch stop_lat for {stop_id}: {row[\"stop_lat\"]} != {s[\"stop_lat\"]}')
            if row['stop_lon'] != s['stop_lon']:
                print(f'Mismatch stop_lon for {stop_id}: {row[\"stop_lon\"]} != {s[\"stop_lon\"]}')

print('Verification complete!')
